function ics(a){var L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FS Invitation//EN','CALSCALE:GREGORIAN'];a.forEach(function(e){L=L.concat(ve(e))});L.push('END:VCALENDAR');return L.join('\r\n')+'\r\n'}
